1	import { reactRouter } from "@react-router/dev/vite";
2	import { defineConfig, type UserConfig } from "vite";
3	import tsconfigPaths from "vite-tsconfig-paths";
4	
5	// Related: https://github.com/remix-run/remix/issues/2835#issuecomment-1144102176
6	// Replace the HOST env var with SHOPIFY_APP_URL so that it doesn't break the Vite server.
7	// The CLI will eventually stop passing in HOST,
8	// so we can remove this workaround after the next major release.
9	if (
10	  process.env.HOST &&
11	  (!process.env.SHOPIFY_APP_URL ||
12	    process.env.SHOPIFY_APP_URL === process.env.HOST)
13	) {
14	  process.env.SHOPIFY_APP_URL = process.env.HOST;
15	  delete process.env.HOST;
16	}
17	
18	const host = new URL(process.env.SHOPIFY_APP_URL || "http://localhost")
19	  .hostname;
20	
21	let hmrConfig;
22	if (host === "localhost") {
23	  hmrConfig = {
24	    protocol: "ws",
25	    host: "localhost",
26	    port: 64999,
27	    clientPort: 64999,
28	  };
29	} else {
30	  hmrConfig = {
31	    protocol: "wss",
32	    host: host,
33	    port: parseInt(process.env.FRONTEND_PORT!) || 8002,
34	    clientPort: 443,
35	  };
36	}
37	
38	export default defineConfig({
39	  server: {
40	    allowedHosts: [host],
41	    cors: {
42	      preflightContinue: true,
43	    },
44	    port: Number(process.env.PORT || 3000),
45	    hmr: hmrConfig,
46	    fs: {
47	      // See https://vitejs.dev/config/server-options.html#server-fs-allow for more information
48	      allow: ["app", "node_modules"],
49	    },
50	  },
51	  plugins: [
52	    reactRouter(),
53	    tsconfigPaths(),
54	  ],
55	  build: {
56	    assetsInlineLimit: 0,
57	  },
58	  optimizeDeps: {
59	    include: ["@shopify/app-bridge-react"],
60	  },
