1	import { PassThrough } from "stream";
2	import { renderToPipeableStream } from "react-dom/server";
3	import { ServerRouter } from "react-router";
4	import { createReadableStreamFromReadable } from "@react-router/node";
5	import { type EntryContext } from "react-router";
6	import { isbot } from "isbot";
7	import { addDocumentResponseHeaders } from "./shopify.server";
8	
9	export const streamTimeout = 5000;
10	
11	export default async function handleRequest(
12	  request: Request,
13	  responseStatusCode: number,
14	  responseHeaders: Headers,
15	  reactRouterContext: EntryContext
16	) {
17	  addDocumentResponseHeaders(request, responseHeaders);
18	
19	  // Allow Chatwoot live-chat widget inside the Shopify admin iframe
20	  const csp = responseHeaders.get("Content-Security-Policy");
21	  if (csp) {
22	    const chatwootDomain = "https://app.chatwoot.com";
23	    let updatedCsp = csp;
24	    updatedCsp = updatedCsp.replace(
25	      /script-src\s/,
26	      `script-src ${chatwootDomain} `,
27	    );
28	    updatedCsp = updatedCsp.replace(
29	      /connect-src\s/,
30	      `connect-src ${chatwootDomain} wss://app.chatwoot.com `,
31	    );
32	    updatedCsp = updatedCsp.replace(
33	      /frame-src\s/,
34	      `frame-src ${chatwootDomain} `,
35	    );
36	    updatedCsp = updatedCsp.replace(
37	      /img-src\s/,
38	      `img-src ${chatwootDomain} `,
39	    );
40	    updatedCsp = updatedCsp.replace(
41	      /style-src\s/,
42	      `style-src ${chatwootDomain} `,
43	    );
44	    responseHeaders.set("Content-Security-Policy", updatedCsp);
45	  }
46	
47	  const userAgent = request.headers.get("user-agent");
48	  const callbackName = isbot(userAgent ?? '')
49	    ? "onAllReady"
50	    : "onShellReady";
51	
52	  return new Promise((resolve, reject) => {
53	    const { pipe, abort } = renderToPipeableStream(
54	      <ServerRouter
55	        context={reactRouterContext}
56	        url={request.url}
57	      />,
58	      {
59	        [callbackName]: () => {
60	          const body = new PassThrough();
61	          const stream = createReadableStreamFromReadable(body);
62	
63	          responseHeaders.set("Content-Type", "text/html");
64	          resolve(
65	            new Response(stream, {
66	              headers: responseHeaders,
67	              status: responseStatusCode,
68	            })
69	          );
70	          pipe(body);
71	        },
72	        onShellError(error) {
73	          reject(error);
74	        },
75	        onError(error) {
76	          responseStatusCode = 500;
77	          console.error(error);
78	        },
79	      }
80	    );
81	
82	    // Automatically timeout the React renderer after 6 seconds, which ensures
83	    // React has enough time to flush down the rejected boundary contents
84	    setTimeout(abort, streamTimeout + 1000);
85	  });
86	}
