5	export const action = async ({ request }: ActionFunctionArgs) => {
6	  const { shop } = await authenticate.webhook(request);
7	
8	  // Webhook requests can trigger multiple times and after an app has already been uninstalled.
9	  // Delete all shop data immediately on uninstall (Shopify App Store requirement).
10	  // The shop/redact GDPR webhook fires 48 hours later and also runs this cleanup.
11	  if (shop) {
12	    try {
13	      await Promise.all([
14	        db.session.deleteMany({ where: { shop } }),
15	        db.zipCode.deleteMany({ where: { shop } }),
16	        db.deliveryRule.deleteMany({ where: { shop } }),
17	        db.waitlistEntry.deleteMany({ where: { shop } }),
18	        db.widgetConfig.deleteMany({ where: { shop } }),
19	        db.subscription.deleteMany({ where: { shop } }),
20	        db.shopSettings.deleteMany({ where: { shop } }),
21	      ]);
22	    } catch {
23	      // Log failures silently — Shopify requires a 200 response regardless
24	    }
25	  }
26	
27	  return new Response();
28	};
