1	/**
2	 * GDPR: customers/data_request
3	 *
4	 * Shopify sends this when a customer requests a copy of their data.
5	 * You must respond within 30 days by sending the data to the customer.
6	 *
7	 * Required for Shopify App Store listing.
8	 * https://shopify.dev/docs/apps/build/privacy-law-compliance
9	 */
10	import type { ActionFunctionArgs } from "react-router";
11	import { authenticate } from "../shopify.server";
12	import db from "../db.server";
13	
14	export const action = async ({ request }: ActionFunctionArgs) => {
15	  const { shop, payload } = await authenticate.webhook(request);
16	
17	  const customerEmail = payload?.customer?.email;
18	
19	  // Look up any data stored for this customer.
20	  // For this app, the only customer PII stored is waitlist entries (email + zip).
21	  // Shopify does not auto-send the data — you must respond within 30 days.
22	  try {
23	    if (customerEmail) {
24	      const customerData = await db.waitlistEntry.findMany({
25	        where: { shop, email: customerEmail },
26	        select: { zipCode: true, status: true, createdAt: true },
27	      });
28	
29	      // Log customer data for manual GDPR response within 30 days.
30	      // In production, integrate with an email service to send data directly.
31	      if (customerData.length > 0) {
32	        console.log(
33	          `[GDPR] Data request for ${customerEmail} at ${shop}:`,
34	          JSON.stringify(customerData),
35	        );
36	      }
37	    }
38	  } catch {
39	    // Shopify requires a 200 response regardless of errors
40	  }
41	
42	  return new Response();
43	};
