298	// Handle GET requests: ?shop=...&zip=...
299	export const loader = async ({ request }: LoaderFunctionArgs) => {
300	  const url = new URL(request.url);
301	
302	  // Handle CORS preflight
303	  if (request.method === "OPTIONS") {
304	    return new Response(null, { status: 204, headers: CORS_HEADERS });
305	  }
306	
307	  const shop = url.searchParams.get("shop");
308	  const zip = url.searchParams.get("zip");
309	  return handleZipCheck(shop, zip);
310	};
