26	const CORS_HEADERS = {
27	  "Access-Control-Allow-Origin": "*",
28	  "Access-Control-Allow-Methods": "POST, OPTIONS",
29	  "Access-Control-Allow-Headers": "Content-Type",
30	  "Content-Type": "application/json",
