44	export const action = async ({ request }: ActionFunctionArgs) => {
45	  if (request.method === "OPTIONS") {
46	    return new Response(null, { status: 204, headers: CORS_HEADERS });
47	  }
48	
49	  if (request.method !== "POST") {
50	    return new Response(JSON.stringify({ error: "Method not allowed" }), {
51	      status: 405,
52	      headers: CORS_HEADERS,
53	    });
54	  }
55	
56	  let shop: string | null = null;
57	  let zip: string | null = null;
58	  let email: string | null = null;
59	  let name: string | null = null;
60	
61	  try {
62	    const body = await request.json();
63	    shop = body?.shop ?? null;
64	    zip = body?.zip ?? null;
65	    email = body?.email ?? null;
66	    name = body?.name ?? null;
67	  } catch {
68	    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
69	      status: 400,
70	      headers: CORS_HEADERS,
71	    });
72	  }
73	
74	  if (!shop || !zip || !email) {
75	    return new Response(
76	      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
77	      { status: 400, headers: CORS_HEADERS },
78	    );
79	  }
80	
81	  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
82	  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
83	    return new Response(
84	      JSON.stringify({ error: "Invalid shop parameter" }),
85	      { status: 400, headers: CORS_HEADERS },
86	    );
87	  }
88	
89	  // Enforce input length limits to prevent abuse
90	  if (zip.length > 20 || email.length > 254) {
91	    return new Response(
92	      JSON.stringify({ error: "Invalid input" }),
93	      { status: 400, headers: CORS_HEADERS },
94	    );
95	  }
96	
97	  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
98	    return new Response(
99	      JSON.stringify({ error: "Invalid email address" }),
100	      { status: 400, headers: CORS_HEADERS },
101	    );
102	  }
103	
104	  // Check if shop's plan allows waitlist
105	  try {
106	    const subscription = await getShopSubscription(shop);
107	    if (subscription.limits.maxWaitlist === 0) {
108	      return new Response(
109	        JSON.stringify({ error: "Waitlist is not available on this store's plan" }),
110	        { status: 400, headers: CORS_HEADERS },
111	      );
112	    }
113	    // Enforce entry limit for Starter plan
114	    if (subscription.limits.maxWaitlist < UNLIMITED) {
115	      const currentCount = await db.waitlistEntry.count({ where: { shop } });
116	      if (currentCount >= subscription.limits.maxWaitlist) {
117	        return new Response(
118	          JSON.stringify({ error: "Waitlist is currently full. Please try again later." }),
119	          { status: 400, headers: CORS_HEADERS },
120	        );
121	      }
122	    }
123	  } catch {
124	    // If subscription check fails, deny the request to prevent plan bypass
125	    return new Response(
126	      JSON.stringify({ error: "Unable to verify subscription. Please try again later." }),
127	      { status: 503, headers: CORS_HEADERS },
128	    );
129	  }
130	
131	  try {
132	    const normalizedZip = normalizeZipCode(zip);
133	
134	    await db.waitlistEntry.upsert({
135	      where: {
136	        shop_email_zipCode: {
137	          shop,
138	          email,
139	          zipCode: normalizedZip,
140	        },
141	      },
142	      create: {
143	        shop,
144	        email,
145	        name: name ? name.trim().substring(0, 100) : null,
146	        zipCode: normalizedZip,
147	        status: "waiting",
148	      },
149	      update: {
150	        status: "waiting",
151	      },
152	    });
153	
154	    // Fire-and-forget: fetch email settings then send emails
155	    db.shopSettings
156	      .findUnique({ where: { shop } })
157	      .then((settings) => {
158	        const emailOpts: EmailOptions = {
159	          senderName: settings?.emailSenderName,
160	          shopDisplayName: settings?.shopName,
161	          replyTo: settings?.emailReplyTo,
162	        };
163	
164	        // Confirmation to customer
165	        sendWaitlistConfirmation(email, normalizedZip, shop, emailOpts).catch(() => {});
166	
167	        // Notify merchant if notificationEmail is set
168	        if (settings?.notificationEmail) {
169	          sendMerchantWaitlistAlert(
170	            settings.notificationEmail,
171	            email,
172	            normalizedZip,
173	            shop,
174	            emailOpts,
175	          ).catch(() => {});
176	        }
177	      })
178	      .catch(() => {});
179	
180	    return new Response(
181	      JSON.stringify({
182	        success: true,
183	        message: "You've been added to the waitlist!",
184	      }),
185	      { status: 200, headers: CORS_HEADERS },
186	    );
187	  } catch {
188	    return new Response(
189	      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
190	      { status: 500, headers: CORS_HEADERS },
191	    );
192	  }
193	};
