1	/**
2	 * Claude Hub Agent Client
3	 *
4	 * Calls global agents from Claude Hub (localhost:3847) during development.
5	 * Drop this file into any Boldteq app's utils/ folder to use agents.
6	 *
7	 * Usage:
8	 *   import { callAgent, listAgents, getAgent } from "~/utils/agent.server";
9	 *
10	 *   // Call an agent with a task
11	 *   const result = await callAgent("quill", "Write an app store listing for Pinzo");
12	 *
13	 *   // List all available agents
14	 *   const agents = await listAgents();
15	 *
16	 *   // Get a specific agent's details
17	 *   const quill = await getAgent("quill");
18	 */
19	
20	const CLAUDE_HUB_URL = process.env.CLAUDE_HUB_URL || "http://localhost:3847";
21	
22	export interface Agent {
23	  filename: string;
24	  name: string;
25	  description: string;
26	  model: string;
27	  body: string;
28	  raw: string;
29	  updatedAt: string;
30	}
31	
32	export interface AgentResult {
33	  success: boolean;
34	  output: string;
35	  agent: string;
36	  error?: string;
37	}
38	
39	/**
40	 * Call a global agent with a prompt.
41	 * Uses Claude Hub's playground endpoint which runs `claude -p` locally.
42	 *
43	 * @param agentName - filename of the agent (e.g. "quill", "vex", "sage")
44	 * @param prompt - the task/prompt to send to the agent
45	 * @param timeoutMs - timeout in ms (default 120s, some agents take a while)
46	 * @returns AgentResult with the agent's output
47	 *
48	 * @example
49	 * const result = await callAgent("quill", "Write a changelog entry for: Added bulk ZIP import");
50	 * console.log(result.output);
51	 */
52	export async function callAgent(
53	  agentName: string,
54	  prompt: string,
55	  timeoutMs = 120000
56	): Promise<AgentResult> {
57	  try {
58	    const controller = new AbortController();
59	    const timeout = setTimeout(() => controller.abort(), timeoutMs);
60	
61	    const response = await fetch(`${CLAUDE_HUB_URL}/api/playground/run`, {
62	      method: "POST",
63	      headers: { "Content-Type": "application/json" },
64	      body: JSON.stringify({ agentName, prompt }),
65	      signal: controller.signal,
66	    });
67	
68	    clearTimeout(timeout);
69	
70	    if (!response.ok) {
71	      throw new Error(`Claude Hub returned ${response.status}`);
72	    }
73	
74	    // Parse SSE stream
75	    const text = await response.text();
76	    const events = text
77	      .split("\n")
78	      .filter((line) => line.startsWith("data: "))
79	      .map((line) => {
80	        try {
81	          return JSON.parse(line.slice(6));
82	        } catch {
83	          return null;
84	        }
85	      })
86	      .filter(Boolean);
87	
88	    // Find the final output
89	    const doneEvent = events.find((e) => e.type === "done" || e.type === "complete");
90	    const errorEvent = events.find((e) => e.type === "error");
91	
92	    if (errorEvent) {
93	      return {
94	        success: false,
95	        output: "",
96	        agent: agentName,
97	        error: errorEvent.error,
98	      };
99	    }
100	
101	    return {
102	      success: true,
103	      output: doneEvent?.output || "",
104	      agent: agentName,
105	    };
106	  } catch (error) {
107	    const message = error instanceof Error ? error.message : "Unknown error";
108	    return {
109	      success: false,
110	      output: "",
111	      agent: agentName,
112	      error: message.includes("abort")
113	        ? `Agent timed out after ${timeoutMs / 1000}s`
114	        : `Claude Hub connection failed: ${message}. Is Claude Hub running on ${CLAUDE_HUB_URL}?`,
115	    };
116	  }
117	}
118	
119	/**
120	 * List all available global agents from Claude Hub.
121	 *
122	 * @example
123	 * const agents = await listAgents();
124	 * agents.forEach(a => console.log(`${a.filename}: ${a.description}`));
125	 */
126	export async function listAgents(): Promise<Agent[]> {
127	  try {
128	    const response = await fetch(`${CLAUDE_HUB_URL}/api/global/agents`);
129	    if (!response.ok) throw new Error(`HTTP ${response.status}`);
130	    return await response.json();
131	  } catch (error) {
132	    console.error("[agent-client] Failed to list agents:", error);
133	    return [];
134	  }
135	}
136	
137	/**
138	 * Get a specific agent's full details (instructions, model, description).
139	 *
140	 * @param agentName - filename of the agent (e.g. "quill")
141	 * @example
142	 * const quill = await getAgent("quill");
143	 * console.log(quill?.body); // Full agent instructions
144	 */
145	export async function getAgent(agentName: string): Promise<Agent | null> {
146	  try {
147	    const response = await fetch(`${CLAUDE_HUB_URL}/api/global/agents/${agentName}`);
148	    if (!response.ok) return null;
149	    return await response.json();
150	  } catch (error) {
151	    console.error(`[agent-client] Failed to get agent ${agentName}:`, error);
152	    return null;
153	  }
154	}
155	
156	/**
157	 * List all agents across all projects (global + project-scoped).
158	 *
159	 * @example
160	 * const all = await listAllAgents();
161	 * all.forEach(a => console.log(`[${a.scope}] ${a.name}`));
162	 */
163	export async function listAllAgents(): Promise<(Agent & { scope: string; projectName?: string })[]> {
164	  try {
165	    const response = await fetch(`${CLAUDE_HUB_URL}/api/unified/agents`);
166	    if (!response.ok) throw new Error(`HTTP ${response.status}`);
167	    return await response.json();
168	  } catch (error) {
169	    console.error("[agent-client] Failed to list all agents:", error);
170	    return [];
171	  }
172	}
